const tabId = 1962625075;

// Let's check window/console or see what network requests were made or if we can run the query via fetch to sparql endpoint
const queryResult = await browserjs(tabId, async () => {
  const query = `## Highly cited publications from db/conf/cvpr/cvpr2022.bht
PREFIX dblp: <https://dblp.org/rdf/schema#>
PREFIX cito: <http://purl.org/spar/cito/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT ?label ?year (COUNT(DISTINCT ?cite) as ?cites) (?publ as ?dblp) (SAMPLE(?dois) as ?doi) WHERE {
  VALUES ?toc { <https://dblp.org/db/conf/cvpr/cvpr2022> } .
  ?publ dblp:listedOnTocPage ?toc .
  ?publ rdfs:label ?label .
  ?publ dblp:omid ?omid .
  OPTIONAL { ?cite cito:hasCitedEntity ?omid . }
  OPTIONAL { ?publ dblp:yearOfPublication ?year } .
  OPTIONAL { ?publ dblp:doi ?dois } .
}
GROUP BY ?label ?year ?publ ?omid
ORDER BY DESC(?cites)
LIMIT 10`;

  try {
    const res = await fetch(`https://sparql.dblp.org/api/dblp?query=${encodeURIComponent(query)}`, {
      headers: {
        'Accept': 'application/sparql-results+json'
      }
    });
    const data = await res.json();
    return { ok: res.ok, status: res.status, data };
  } catch (e) {
    return { error: e.toString() };
  }
});

console.log("Fetch result:", JSON.stringify(queryResult, null, 2));

